<script setup lang="ts">
import { isProjectManager } from '../../../../shared/src/permissions';
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import type { RiskAlert, RiskWorkspace } from '../../../../shared/src/risks';
import { snoozeRiskAlert } from '../../api/risks';
import { PlanningError } from '../../api/planning';
import { dateTime } from './labels';
import '../tasks/task-drawer.css';
const props = defineProps<{ workspace: RiskWorkspace; alert: RiskAlert; actorId: string }>();
const emit = defineEmits<{ close: []; saved: [message:string]; reload: []; convert: []; risk: [id:string]; task: [id:string] }>();
const dialog = ref<HTMLDialogElement>(), reason = ref(''), until = ref(''), snoozing = ref(false), confirmed = ref(false), busy = ref(false), error = ref(''), notice = ref(''), stale = ref(false), reloading = ref(false), confirmLeave = ref(false);
const expectedVersion = ref(props.alert.version);
const writable = computed(()=>props.workspace.actors.some(a=>a.id===props.actorId && isProjectManager(a.role)));
const dirty = computed(()=>!!reason.value || !!until.value);
let leaveAction: (()=>void)|null = null, resolver: ((allowed:boolean)=>void)|null = null;
function reveal() { confirmLeave.value=true; nextTick(()=>dialog.value?.querySelector<HTMLElement>('.td-leave-panel')?.scrollIntoView({block:'nearest'})); }
function leave(action=()=>emit('close')) { if(busy.value)return;if(dirty.value){leaveAction=action;reveal();}else action(); }
function confirmNavigation():Promise<boolean>{if(busy.value)return Promise.resolve(false);if(!dirty.value)return Promise.resolve(true);return new Promise(resolve=>{resolver?.(false);resolver=resolve;leaveAction=()=>{resolver?.(true);resolver=null;};reveal();});}
function discard(){confirmLeave.value=false;const action=leaveAction;leaveAction=null;action?.();}
function keep(){confirmLeave.value=false;leaveAction=null;resolver?.(false);resolver=null;}
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value||busy.value){event.preventDefault();event.returnValue='';}}
function review(){error.value='';if(!reason.value.trim()||!until.value||until.value<=props.workspace.today){error.value='请填写暂缓原因和未来截止日期。';return;}confirmed.value=true;}
let signature='', key='';
async function save(){if(busy.value||stale.value||!confirmed.value)return;busy.value=true;error.value='';const body={expectedVersion:expectedVersion.value,reason:reason.value.trim(),until:until.value};const next=JSON.stringify({body,actor:props.actorId,token:props.workspace.writeToken});if(next!==signature){signature=next;key=crypto.randomUUID();}try{await snoozeRiskAlert(props.workspace,props.actorId,props.alert.id,body,key);reason.value='';until.value='';emit('saved','预警已暂缓；到期会重新检查，台账风险不会自动关闭。');}catch(e){error.value=e instanceof Error?e.message:'暂缓失败，请重试。';stale.value=e instanceof PlanningError&&[403,409].includes(e.status);}finally{busy.value=false;}}
function reload(){reloading.value=true;emit('reload');}
watch(()=>props.workspace,()=>{if(!reloading.value)return;expectedVersion.value=props.alert.version;reloading.value=false;stale.value=false;confirmed.value=false;error.value='';signature='';notice.value='已读取最新预警，暂缓草稿保留，请重新核对。';});
defineExpose({confirmNavigation});
onMounted(()=>{dialog.value?.showModal();window.addEventListener('beforeunload',beforeUnload);});onBeforeUnmount(()=>{dialog.value?.close();window.removeEventListener('beforeunload',beforeUnload);resolver?.(false);});
</script>
<template><dialog ref="dialog" class="task-drawer risk-drawer" aria-labelledby="alert-title" :aria-busy="busy" @cancel.prevent="leave()"><div class="td-shell"><header class="td-header"><div class="td-header-row"><span class="td-reference">自动预警<span v-if="workspace.project.isDemo"> · DEMO · 示例项目</span></span><button class="td-icon-button" aria-label="关闭预警详情" :disabled="busy" @click="leave()">×</button></div><h2 id="alert-title" :title="alert.title">{{ alert.title }}</h2><p class="td-stream">{{ {open:'待处理',snoozed:'已暂缓',resolved:'已恢复'}[alert.status] }} · 规则版本 {{ alert.ruleVersion }}</p></header><div class="td-body"><div v-if="confirmLeave" class="td-leave-panel" role="alert"><strong>暂缓说明尚未保存</strong><div class="td-inline-buttons"><button class="button" @click="keep">继续填写</button><button class="button" @click="discard">放弃草稿并继续</button></div></div><div v-if="error" class="td-error" role="alert">{{ error }}<button v-if="stale" class="td-text-button" @click="reload">保留草稿并读取最新记录</button></div><p v-if="notice" class="td-notice" role="status">{{ notice }}</p><p class="td-callout">按 Asia/Shanghai 当前日 {{ workspace.today }} 检查。自动预警提供证据，人工评估决定风险概率与影响；恢复不会自动关闭风险台账。</p><p v-if="alert.sourceDeleted" class="td-warning-text">关联任务已删除，保留此历史预警；删除不代表风险已解决。</p><h3>触发证据</h3><p class="td-prose">{{ alert.evidence }}</p><dl class="td-facts"><div><dt>首次触发</dt><dd>{{ dateTime(alert.firstTriggeredAt) }}</dd></div><div><dt>最近触发</dt><dd>{{ dateTime(alert.lastTriggeredAt) }}</dd></div></dl><p v-if="alert.snoozedUntil" class="td-callout">暂缓至 {{ alert.snoozedUntil }}：{{ alert.snoozeReason }}</p><section class="td-section"><h3>关联任务</h3><p v-if="!alert.taskIds.length" class="td-empty-inline">此预警为工作分组或规则范围，没有单项任务链接。</p><button v-for="id in alert.taskIds.filter(id=>workspace.tasks.some(t=>t.id===id && t.taskKind!=='summary' && !t.isContainer))" :key="id" class="td-related-task" @click="leave(()=>emit('task',id))">{{ workspace.tasks.find(t=>t.id===id)?.title || id }} ↗</button></section><section v-if="alert.linkedRiskId" class="td-section"><h3>已转为台账风险</h3><button class="td-text-button" @click="leave(()=>emit('risk',alert.linkedRiskId!))">查看关联风险</button></section><section v-if="snoozing" class="td-action-panel"><h3>暂缓预警</h3><form id="alert-snooze-form" class="td-form" @submit.prevent="review"><fieldset :disabled="busy||confirmed||stale"><label class="td-field">暂缓原因<textarea v-model="reason" required rows="3" maxlength="2000"></textarea></label><label class="td-field">暂缓至<input v-model="until" required type="date" :min="workspace.today"/></label></fieldset></form><div v-if="confirmed"><p class="td-prose">将“{{ alert.title }}”暂缓至 {{ until }}。原因：{{ reason }}。到期仍命中规则时重新打开。</p><button class="td-text-button" :disabled="busy" @click="confirmed=false">返回修改</button></div></section><section class="td-section"><h3>活动记录</h3><article v-for="event in [...alert.events].reverse()" :key="event.id" class="td-event"><div><h4>{{ event.actor }} · {{ event.action }}</h4><p class="td-prose">{{ event.text }}</p><time>{{ dateTime(event.createdAt) }}</time></div></article></section></div><footer class="td-footer"><template v-if="snoozing"><button class="button" :disabled="busy" @click="leave(()=>{snoozing=false;confirmed=false;reason='';until=''})">取消暂缓</button><button v-if="!confirmed" class="button primary" form="alert-snooze-form" :disabled="stale">核对暂缓</button><button v-else class="button primary" :disabled="busy||stale" @click="save">{{ busy?'正在保存…':'确认暂缓预警' }}</button></template><template v-else><button v-if="writable && alert.status!=='resolved'" class="button" @click="snoozing=true">暂缓预警</button><button v-if="writable && !alert.linkedRiskId" class="button primary" @click="emit('convert')">转为风险</button><button v-if="!writable" class="button" @click="leave()">返回自动预警</button></template></footer></div></dialog></template>
